if nargin<2
outval=4
end
outliers=(isnan(data) |abs(data)==inf);
% 筛 选 出 异常 字符 或 者 绝对 值 为 无 穷 大 的 作为 异常 数据
[n,m]=size(data);
if m>1,
data(any(outliers'),:)=[];
else
data(find(outliers'),:)=[];
end
[n,m]=size(data);
